#!/bin/bash
set -e
echo "Unpacking Lumen project..."
base64 -d <<'LUMEN_B64_END' > lumen.tar.gz

LUMEN_B64_END
tar xzf lumen.tar.gz
rm lumen.tar.gz
cd lumen
echo "Installing dependencies (this takes a minute)..."
npm install
echo ""
echo "✅ Done! Now:"
echo "1. Add your Supabase anon key to lumen/.env.local (rename from .env.local.example)"
echo "2. Run: npm run dev"
echo "3. Click the popup / Ports tab to open the preview in your browser"
